'use client';
/**
 * B80 §TK (F-P7-E-03: UX-18-001…005, TYP-013/014/015) — THE TEXT ROLES of the shared library, on the type tokens (the classes are
 * generated by packages/tokens: .eye-text-<role>, tabular numerals for numbers and instants, the mono stack for identifiers and digests):
 *   Identifier / Digest   a long value shortened in the MIDDLE, the full value its accessible name and its title, COPIED IN FULL;
 *   NumberValue           Intl for the active locale, tabular, the UNIT KEPT beside it (never converted), the canonical value copied;
 *   Timestamp             the instant with its time zone stated; a DATE as the day it names;
 *   Statement             fact | recommendation | decision — three distinct typographic roles (UX-18-004): a recommendation is never typed
 *                         as a fact or an approval, and a decision without its actor is not shown as decided.
 * The decisions are lib/format-b80.ts's (pure, unit-tested); the fonts are the fallback stacks (TYP-001/002: the vendored fonts are B81's).
 */
import { useState, type ReactNode } from 'react';
import { copyText, formatInstant, formatNumber, middleEllipsis, statementView, type StatementRole } from '../lib/format-b80';

function CopyButton({ value, what }: { value: string; what: string }) {
  const [state, setState] = useState<'idle' | 'copied' | 'failed'>('idle');
  return (
    <button type="button" className="eye-copy" aria-label={`Copy the full ${what}`} onClick={() => {
      void navigator.clipboard.writeText(value).then(() => setState('copied'), () => setState('failed'));
    }}>
      {state === 'copied' ? 'Copied' : state === 'failed' ? 'Copy failed' : 'Copy'}
    </button>
  );
}

export function Identifier({ value, max, copy }: { value: string; max?: number; copy?: boolean }) {
  const s = middleEllipsis(value, max ?? 24);
  return (
    <span className="eye-text-identifier" title={s.full}>
      <span aria-hidden={s.truncated ? true : undefined}>{s.shown}</span>
      {s.truncated ? <span className="eye-visually-hidden">{s.full}</span> : null}
      {copy === false ? null : <CopyButton value={s.full} what="identifier" />}
    </span>
  );
}

export function Digest({ value, max }: { value: string; max?: number }) {
  const s = middleEllipsis(value, max ?? 20);
  return (
    <span className="eye-text-digest" title={s.full}>
      <span aria-hidden={s.truncated ? true : undefined}>{s.shown}</span>
      {s.truncated ? <span className="eye-visually-hidden">{s.full}</span> : null}
      <CopyButton value={s.full} what="digest" />
    </span>
  );
}

export function NumberValue({ value, unit, locale, fractionDigits }: { value: number | string | null; unit?: string | null; locale?: string; fractionDigits?: number }) {
  const f = formatNumber(value, { ...(unit === undefined ? {} : { unit }), ...(locale === undefined ? {} : { locale }), ...(fractionDigits === undefined ? {} : { fractionDigits }) });
  return (
    <span className="eye-text-value" title={f.note ?? undefined} data-canonical={copyText(f)}>
      <span className="eye-text-number">{f.text}</span>
      {f.unit !== null ? <> <span className="eye-text-unit">{f.unit}</span></> : null}
      {f.note !== null && f.state !== 'value' ? <span className="eye-visually-hidden"> ({f.note})</span> : null}
    </span>
  );
}

export function Timestamp({ value, timeZone, locale }: { value: string | null; timeZone?: string; locale?: string }) {
  const t = formatInstant(value, { ...(timeZone === undefined ? {} : { timeZone }), ...(locale === undefined ? {} : { locale }) });
  return t.canonical === '' ? <span className="eye-text-timestamp">—</span> : <time className="eye-text-timestamp" dateTime={t.canonical}>{t.text}</time>;
}

export function Statement({ role, actor, children }: { role: StatementRole; actor?: string | null; children: ReactNode }) {
  const v = statementView(role, actor);
  if (v.problem !== null) return <p className="eye-text-fact" role="note">NOT SHOWN AS DECIDED — {v.problem}: {children}</p>;
  return <p className={v.className} data-statement={role}>{v.prefix !== null ? <strong className="eye-text-label">{v.prefix}: </strong> : null}{children}</p>;
}
